function paint(rows: string[]): HTMLCanvasElement {
  const w = Math.max(...rows.map(r => r.length));
  const p = new PixelCanvas(w, rows.length);
  const each = (glow: boolean) =>
    rows.forEach((r, y) => [...r].forEach((ch, x) => ch !== '.' && GLOW.includes(ch) === glow && p.px(x, y, PAL[ch])));
  each(false);
  p.outline('auto', 0.3);
  each(true);
  return p.toCanvas();
}

